using System;using System.Collections.Generic;using System.IO;using UnityEngine;using UnityEditor;
public static class RetroKingdomFollowupInstaller {
 const string Root="Assets/Resources/RetroDungeonExperiment";
 static T Asset<T>(string path)where T:ScriptableObject{var value=AssetDatabase.LoadAssetAtPath<T>(path);if(value==null){value=ScriptableObject.CreateInstance<T>();AssetDatabase.CreateAsset(value,path);}return value;}
 static WorldDialogueLine L(string speaker,string text){return new WorldDialogueLine(speaker,text);}
 [MenuItem("Editor/Experimentos/Configurar reino y avisos de ciudad")]
 public static string Install(){
 var settings=AssetDatabase.LoadAssetAtPath<RetroDungeonSettings>(Root+"/Settings.asset");
 var audio=Asset<DungeonAudioSettings>(Root+"/Audio.asset");EditorUtility.CopySerialized(Resources.Load<DungeonAudioSettings>("Audio/DungeonAudioSettings"),audio);
 audio.explorationPlaylist=new[]{AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/Music/Retro Dungeon/Pixel Platformer.wav"),AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/Music/Retro Dungeon/Pixel Platformer 2.wav")};audio.normalCombatPlaylist=new[]{AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/Music/Retro Dungeon/Bit-Battle.wav"),AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/Music/Retro Dungeon/Bit-Battle 2.wav")};settings.audioProfile=audio;settings.frontPipe=AssetDatabase.LoadAssetAtPath<Texture2D>(Root+"/Layers/FrontPipe.png");
 var frontImporter=(TextureImporter)AssetImporter.GetAtPath(Root+"/Layers/FrontPipe.png");frontImporter.textureCompression=TextureImporterCompression.Uncompressed;frontImporter.filterMode=FilterMode.Point;frontImporter.alphaIsTransparency=true;frontImporter.SaveAndReimport();
 settings.frontPipes=new[]{new RetroFrontPipeDefinition{id="retro.pipe.front.north",cell=new Vector2Int(5,12),direction=0,placementIds=new[]{"retro.front.north.0"}},new RetroFrontPipeDefinition{id="retro.pipe.front.west",cell=new Vector2Int(11,15),direction=3,placementIds=new[]{"retro.front.west.0"}}};
 var map=AssetDatabase.LoadAssetAtPath<DungeonMapSettings>(Root+"/Map.asset");map.regions.initialRandomPerZone=2;var encounter=AssetDatabase.LoadAssetAtPath<EnemyEncounterSettings>(Root+"/Encounters.asset");encounter.encounterDirectorEnabled=true;encounter.directorCheckEverySteps=2;encounter.longQuietWalkSteps=16;encounter.spawnOutsideView=true;EditorUtility.SetDirty(encounter);var placements=new List<PlacedEnemyDefinition>(map.regions.placedEnemies);foreach(var pipe in settings.frontPipes)foreach(var id in pipe.placementIds)if(!placements.Exists(p=>p.id==id))placements.Add(new PlacedEnemyDefinition{id=id,speciesId="Hongo",cell=pipe.cell,trigger=EncounterTrigger.InteractiveEvent,unique=true,respawn=false,holdPosition=true,randomLevel=false,fixedLevel=1,exploration=new EnemyExplorationSettings{profile=EnemyExplorationProfile.Static,persistence=EnemyExplorationPersistence.PermanentDefeat}});map.regions.placedEnemies=placements.ToArray();
 Directory.CreateDirectory(Root+"/Normals");var normals=new List<RetroNormalLayer>();foreach(var guid in AssetDatabase.FindAssets("t:Texture2D",new[]{Root+"/Layers"})){var source=AssetDatabase.GUIDToAssetPath(guid);if(source.EndsWith("Sky.png"))continue;var path=Root+"/Normals/"+Path.GetFileNameWithoutExtension(source)+"-Normal.png";if(!File.Exists(path))File.Copy(source,path);AssetDatabase.ImportAsset(path);var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.textureType=TextureImporterType.NormalMap;importer.convertToNormalmap=true;importer.heightmapScale=.035f;importer.filterMode=FilterMode.Point;importer.wrapMode=source.EndsWith("Floor.png")?TextureWrapMode.Repeat:TextureWrapMode.Clamp;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.SaveAndReimport();normals.Add(new RetroNormalLayer{texture=AssetDatabase.LoadAssetAtPath<Texture2D>(source),normal=AssetDatabase.LoadAssetAtPath<Texture2D>(path)});}settings.normalMaps=normals.ToArray();
 var city=DigitalKingdomSettings.Current;var guide=Asset<DigitalKingdomLocation>("Assets/Resources/DigitalKingdom/Locations/08-city.dungeons.asset");guide.id="city.dungeons";guide.displayName="Explorar dungeons";guide.npcName="GUÍA";guide.description="Habla con el guía y elige un reino para explorar.";guide.service=DigitalKingdomService.DungeonGuide;guide.available=guide.initiallyUnlocked=guide.uniqueConversation=true;guide.dialogue=new[]{L("GUÍA","Llevo exploradores a otros reinos. ¿A dónde quieres ir?"),L("GAMERBOY","Esa es una buena pregunta... No sé a dónde debo ir."),L("GUÍA","Entonces date una vuelta por la ciudad. A veces una conversación basta para encontrar el camino.")};var locations=new List<DigitalKingdomLocation>(city.locations);locations.RemoveAll(l=>l!=null&&l.id==guide.id);int sewers=locations.FindIndex(l=>l!=null&&l.service==DigitalKingdomService.Sewers);locations.Insert(sewers>=0?sewers+1:locations.Count,guide);city.locations=locations.ToArray();
 var story=Asset<DigitalKingdomStorySettings>("Assets/Resources/DigitalKingdom/Story.asset");story.noDestinationDialogue=new[]{L("GUÍA","¿Ya sabes a dónde quieres ir?"),L("GAMERBOY","Todavía no. Sigo buscando una pista."),L("GUÍA","Pregunta por la ciudad. Yo estaré aquí cuando tengas un destino.")};story.notices=new[]{
 new CityNoticeRule{id="city.rumor.pixel.v1",locationId="city.inn",requireAllLocationsVisited=true,grantFlags=new[]{"pixel.rumor.heard"},dialogue=new[]{L("POSADERO","Antes de que te vayas... Escuché a alguien en el bar hablar de problemas en el Reino del Píxel."),L("GAMERBOY","¿Qué clase de problemas?"),L("POSADERO","Decía que las tuberías están soltando criaturas y que algunos caminos ya no son seguros."),L("GAMERBOY","Por fin un lugar donde empezar a buscar respuestas."),L("POSADERO","Habla con el guía de dungeons. Él conoce el camino.")}},
 new CityNoticeRule{id="city.guide.pixel.v1",locationId=guide.id,requiredFlags=new[]{"pixel.rumor.heard"},grantFlags=new[]{"pixel.route.unlocked"},dialogue=new[]{L("GUÍA","Veo que ya tienes algo en mente."),L("GAMERBOY","Me hablaron de problemas en el Reino del Píxel. Quiero ir allí."),L("GUÍA","Conozco la ruta. No te fíes de las tuberías: algunas tienen visitas."),L("GAMERBOY","Claro. Hasta las tuberías tienen más vida social que yo."),L("GUÍA","Cuando estés listo, elige el reino. Podrás regresar a Digital Kingdom desde el menú de pausa.")}}};story.destinations=new[]{new CityDungeonDestination{id="kingdom.pixel",displayName="Reino del Píxel",scenePath="Assets/Scenes/RetroDungeonExperiment.unity",map=map,requiredFlag="pixel.route.unlocked"}};city.story=story;
 foreach(var item in new UnityEngine.Object[]{settings,audio,map.regions,city,guide,story})EditorUtility.SetDirty(item);var scenes=new List<EditorBuildSettingsScene>(EditorBuildSettings.scenes);if(!scenes.Exists(s=>s.path=="Assets/Scenes/RetroDungeonExperiment.unity"))scenes.Add(new EditorBuildSettingsScene("Assets/Scenes/RetroDungeonExperiment.unity",true));EditorBuildSettings.scenes=scenes.ToArray();AssetDatabase.SaveAssets();return "Configured 2+2 songs, "+normals.Count+" normal imports, 2 front pipes and city story";
 }
}
